async function startRideTrack(leg,resume=false){const kept=resume?stored('jb.rideTrack',null):null;stopRideTrack();ride.samples=kept?.id===leg.id?kept.samples||[]:[];ride.warned=false;ride.leg=leg;if(ride.samples.length)saveTrack(leg);ride.stops=[{lat:leg.lat,lng:leg.lng}];api(`/api/board/next?id=${encodeURIComponent(leg.stopId)}&no=${encodeURIComponent(leg.no)}`).then(r=>{ride.stops=[{lat:leg.lat,lng:leg.lng},...r.stops];}).catch(()=>{});if(!navigator.geolocation)return;rideWatch=navigator.geolocation.watchPosition(p=>{const before=ride.samples.length;ride.samples=addSample(ride.samples,{t:Date.now(),lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy||0});if(ride.samples.length!==before)saveTrack(leg);if(!ride.warned&&looksOff(ride.samples,ride.stops)){ride.warned=true;toast(t('rideOffHint'));}},()=>{},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});try{rideLock=await navigator.wakeLock?.request('screen');}catch{}}
