async function pullProgress(){if(!state.status.user)return;try{const {data}=await api('/api/me/progress'),merged=mergeProgress(readProgress(),data);for(const [name,key] of Object.entries(SYNC_KEYS))if(merged[name]!==null&&merged[name]!==undefined)localStorage.setItem(key,JSON.stringify(merged[name]));applySkin();render();await pushProgress();}catch{}}
const myStops=()=>stored('jb.myStops',[]);
