async function fetchTour(){const T=state.tour,f=T.from;try{const r=await api(`/api/tour${f?`?lat=${f.lat}&lng=${f.lng}`:''}`);if(T.from!==f)return;T.spots=r.spots;T.boards={};if(state.view==='tour'){render();focusTour();}const list=boardsToLoad(r.spots);await Promise.allSettled(list.map(async b=>{T.boards[b.id]=await api(`/api/board/stop?id=${encodeURIComponent(b.id)}`);}));if(state.view==='tour'&&T.from===f)render();}catch(error){T.error=error.key||'connectionError';T.spots=T.spots||[];if(state.view==='tour')render();}}
