let tourTimer=0;
function tourSearch(q){state.tour.q=q;clearTimeout(tourTimer);tourTimer=setTimeout(async()=>{let hits=[];if(q.trim().length>=2){try{hits=(await api(`/api/board/named?q=${encodeURIComponent(q.trim())}`)).stops.slice(0,8);}catch{}}if(state.tour.q!==q)return;state.tour.hits=hits;const ul=document.querySelector('.tr-hits');if(ul)ul.innerHTML=tourHits(hits,e,t);},250);}
function tourMap(s){const tr=s.trips?.[0],f=state.tour.from,pts=[...(tr?[{name:tr.board.name,lat:tr.board.lat,lng:tr.board.lng,role:'board',label:tr.no},{name:tr.off.name,lat:tr.off.lat,lng:tr.off.lng,role:'off',label:tr.no}]:[]),{name:t(`hbSpot_${s.id}`),sub:s.stop.name,lat:s.stop.lat,lng:s.stop.lng,role:'dest'}];openPlacesMap({t,me:f?.kind==='me'?f:null,choices:[],points:pts,onStop:p=>{const st=[tr?.board,tr?.off,s.stop].find(x=>x&&Math.abs(x.lat-p.lat)<1e-6&&Math.abs(x.lng-p.lng)<1e-6);if(st){state.view='explore';chooseStop({id:st.id,name:st.name,lat:st.lat,lng:st.lng});}}});}
// 최근 검색: 노선·정류장·목적지·경로를 고르면 남긴다. 지운 항목은 계정에서 되살아나지 않게 지운 기록을 남긴다.
