function goPath(from,to,toName=''){state.view='explore';state.pane='search';state.sheet=true;state.mode='destination';state.from=from?.lat!=null?from:null;state.origin=from?.name||'';state.to=to?.lat!=null?to:null;state.query=to?.name||toName;state.results=null;state.error=null;state.route=null;state.stop=null;state.routeStops=[];state.vehicles=[];render();search();}
function goQuery(name){state.view='explore';state.pane='search';state.sheet=true;state.mode='destination';state.to=null;state.query=name;state.results=null;state.error=null;state.route=null;state.stop=null;state.routeStops=[];state.vehicles=[];render();const ask=()=>{toast(t('favPlaceOrigin'));document.querySelector('#origin-input')?.focus();};if(state.from){search();return;}if(!navigator.geolocation){ask();return;}navigator.geolocation.getCurrentPosition(p=>{state.from={lat:p.coords.latitude,lng:p.coords.longitude,name:t('current')};state.origin=state.from.name;search();},ask,{timeout:8000,maximumAge:60000});}
