const forget=key=>store('jb.favGone',markGone(stored('jb.favGone',{}),key));
const remember=key=>{const gone={...stored('jb.favGone',{})};delete gone[key];store('jb.favGone',gone);};
function setStopFav(stop){const list=myStops(),on=list.some(s=>s.id===stop.id);if(!on&&list.length>=MAX_STOPS){toast(t('favFull',{n:MAX_STOPS}));return false;}if(on)forget(`stop:${stop.id}`);else remember(`stop:${stop.id}`);store('jb.myStops',on?list.filter(s=>s.id!==stop.id):[...list,{id:stop.id,name:stop.name,lat:stop.lat,lng:stop.lng,at:Date.now()}]);return true;}
function setPlaceFav(place){const list=places(),id=placeId(place),on=list.some(p=>p.id===id);if(!on&&list.length>=MAX_PLACES){toast(t('favFull',{n:MAX_PLACES}));return false;}if(on)forget(`place:${id}`);else remember(`place:${id}`);store('jb.places',on?list.filter(p=>p.id!==id):[...list,toPlace(place)]);return true;}
