async function favSearch(){const s=favSheetState,q=s.query.trim(),ticket=++s.ticket;if(s.tab==='bus'){s.hits=filterNumbers(state.tt.numbers,q).slice(0,8).map(no=>({kind:'bus',no,name:t('liveMap'),item:{number:no}}));drawFavLists();return;}if(q.length<2){s.hits=[];drawFavLists();return;}try{const hits=s.tab==='stop'?(await api(`/api/board/named?q=${encodeURIComponent(q)}`)).stops.map(x=>({kind:'stop',name:x.name,sub:x.next?t('boardNext',{stop:x.next}):'',item:x})):(await lookupPlaces(q)).map(x=>({kind:'place',name:x.name,sub:x.address,item:x}));if(ticket===s.ticket){s.hits=hits;drawFavLists();}}catch(error){if(ticket===s.ticket)toast(t(error.key||'connectionError'));}}
async function favToggle(index){const s=favSheetState,list=[...s.hits,...favSaved()],hit=list[Number(index)];if(!hit)return;if(hit.kind==='stop'){setStopFav(hit.item);refreshHome();}else if(hit.kind==='place')setPlaceFav(hit.item);else{let r=state.favorites.find(x=>x.number===hit.no);if(!r){const g=(await api(`/api/route-groups?q=${encodeURIComponent(hit.no)}`)).groups?.[0];if(!g)return;r={id:g.variantIds[0],number:hit.no,start:g.from,end:g.to};}await setRouteFav(r);}drawFavLists();render();}
