function goPlace(place){state.view='explore';state.pane='search';state.sheet=true;state.mode='destination';state.to=place;state.query=place.name;state.results=null;state.error=null;state.route=null;state.stop=null;state.routeStops=[];state.vehicles=[];render();const ask=()=>{if(state.from){search();return;}toast(t('favPlaceOrigin'));document.querySelector('#origin-input')?.focus();};if(!navigator.geolocation){ask();return;}navigator.geolocation.getCurrentPosition(p=>{state.from={lat:p.coords.latitude,lng:p.coords.longitude,name:t('current')};state.origin=state.from.name;search();},ask,{timeout:8000,maximumAge:60000});}
