 if(d.view){if(d.view==='map'&&state.mode!=='route'){++searchVersion;++selectionVersion;state.mode='route';state.query=state.route?.number||'';state.results=state.route?{kind:'routes',items:[state.route]}:null;state.lines=[];state.error=null;state.busy=false;}state.view=d.view;state.pane=d.view==='community'?'community':d.view==='explore'?'search':'map';render();if(d.view==='today')loadToday();if(d.view==='home')refreshHome();if(d.view==='tour')loadTour();if(d.view==='favorites')loadQuest();if(d.view==='timetable'||d.view==='map')loadNumbers();if(d.view==='community'){if(!state.posts.length)reloadPosts();else freshCommunity();roomPing();roomTick();waitTick();}return;}
 // 내 보드
 if(d.hbStop){const s=knownStop(d.hbStop);if(s){state.view='explore';await chooseStop(s);}return;}
 if(d.hbRode){const s=knownStop(d.hbAt);if(s){const prev=state.stop;state.stop=s;rodeBus(d.hbRode,Number(d.hbMin));state.stop=prev;render();}return;}
 if(d.hbRoute!==undefined){const r=frequentRoutes(stored('jb.trips',[]))[Number(d.hbRoute)];if(r)goPath({name:r.stopName,lat:r.lat,lng:r.lng},r.offLat!=null?{name:r.offName,lat:r.offLat,lng:r.offLng}:null,r.offName);return;}
 if(d.hbAgain!==undefined){const l=recentRides(stored('jb.trips',[]))[Number(d.hbAgain)];if(l){state.view='explore';await chooseStop(knownStop(l.stopId)||{id:l.stopId,name:l.stopName});state.openRow=l.no;render();}return;}
 if(d.hbRecentDrop){forget('recent:'+d.hbRecentDrop);store('jb.recent',dropRecent(stored('jb.recent',[]),d.hbRecentDrop));render();return;}
 if(d.hbRecent){const r=stored('jb.recent',[]).find(x=>x.key===d.hbRecent);if(r)await replayRecent(r);return;}
