 // 관광노선
 if(d.tourSort){state.tour.sort=d.tourSort;render();return;}
 if(d.tourTheme){state.tour.theme=d.tourTheme;render();return;}
 if(d.tourFrom){const T=state.tour;T.error=null;if(d.tourFrom==='me'){T.asked=false;T.from=null;T.picking=false;T.spots=null;loadTour();return;}setTourFrom(knownStop(d.tourFrom.slice(5)));return;}
 if(d.tourHit){setTourFrom(state.tour.hits.find(x=>x.id===d.tourHit));return;}
