 if(d.mode){const fromLive=state.view==='map';if(fromLive){state.view='explore';state.pane='search';}else if(d.mode===state.mode&&!state.sheet){state.sheet=true;render();return;}state.sheet=true;++searchVersion;++selectionVersion;state.busy=false;state.mode=d.mode;state.query='';state.results=null;state.error=null;state.route=null;state.stop=null;state.routeStops=[];state.vehicles=[];state.lines=[];render();return;}
 if(d.sort){state.sort=d.sort;await selectPath(sorted()[0],false);render();return;}
 if(d.place!==undefined){const p=state.results.items[Number(d.place)],target=state.results.target;if(target==='origin'){state.from=p;state.origin=p.name;}else{state.to=p;state.query=p.name;}state.results=null;await search();return;}
 if(d.searchRoute){dialog.close();state.mode='route';state.query=d.searchRoute;state.results=null;await search();return;}
 if(d.topQ){state.view='community';state.pane='community';state.ctab='live';state.topHide=state.topQ?.id;render();roomPing();await roomTick();document.querySelector('#room-input')?.focus();return;}if(d.topQHide){state.topHide=d.topQHide;store('jb.topHide',d.topQHide);document.querySelector('#top-q').innerHTML='';return;}if(d.ctab){state.ctab=d.ctab;state.category='all';render();if(d.ctab==='notice'){loadToday();return;}freshCommunity();roomPing();roomTick();return;}
 if(d.roomRadius!==undefined){const r=Number(d.roomRadius);state.room.radius=r;if(r&&!state.room.point){roomLocate();return;}render();roomTick();return;}
 if(d.roomBot){state.room.bot=!state.room.bot;render();return;}
