 if(d.kudo){try{const {counts}=await api('/api/kudos',postOptions({routeNo:d.kudoNo,type:d.kudo}));questAct('kudo');const key=`jb.kudos.${new Date().toISOString().slice(0,10)}`,done=stored(key,{});done[d.kudoNo]=[...(done[d.kudoNo]||[]),d.kudo];store(key,done);drawKudos(d.kudoNo,counts);toast(t(d.kudo==='crowded'?'reportThanks':'kudoThanks'));}catch(error){toast(t(error.key||'connectionError'));}return;}
 // 탐험 수첩
 if(d.qTab){state.qtab=d.qTab;render();return;}
 if(d.qCert!==undefined){state.qcert=!state.qcert;render();return;}
 if(d.qPlace){showModal(placeSheet(d.qPlace,questState().cards.includes(d.qPlace),e,t));return;}
 if(d.qRules){showModal(rulesSheet(t));return;}
 if(d.qSpin){const q=questState();if(q.tickets<1)return;const r=rollTicket();q.tickets-=1;q.coins+=r.coins;q.xp+=r.coins;saveQuest(q);showModal(spinSheet(r,e,t));render();return;}
 if(d.qTeam){const q=questState();q.team=d.qTeam;saveQuest(q);render();return;}
 if(d.qSkin){const q=questState(),id=d.qSkin,price=Number(d.qPrice);if(!q.owned.includes(id)){if(q.coins<price)return;q.coins-=price;q.owned.push(id);}q.skin=q.skin===id?null:id;saveQuest(q);applySkin();render();return;}
 if(d.logOff){await showOffSheet();return;}
 if(d.logStop){const s=state.offStops?.find(x=>x.id===d.logStop);if(s){finishRide(s);}return;}
 if(d.logSkip){stopRideTrack();ride.samples=[];store('jb.trips',finishLeg(stored('jb.trips',[]),{stopName:null,at:Date.now()}));dialog.close();render();return;}
 if(d.rideConfirm){const yes=d.rideConfirm==='yes';await finalizeRide(state.pendingOff,state.pendingCheck,yes);return;}
 if(d.logClear){if(confirm(t('logClearAsk'))){store('jb.trips',[]);render();}return;}
 if(d.noticeOpen){await openNotice(d.noticeOpen);return;}if(d.liveNo){await openLive(d.liveNo);return;}if(d.ttBase){state.tt.mode=d.ttBase;state.tt.picking=false;if(d.ttBase==='route'){if(!state.tt.numbers.length)loadNumbers();}else if(state.route){state.route=null;}render();return;}
