 if(d.ttPickPartner){const s=state.board?.partners?.find(x=>x.id===d.ttPickPartner);if(s)await ttChoose(s);return;}
 if(d.ttName){try{await ttChoose(await api(`/api/board/find?q=${encodeURIComponent(d.ttName)}`));}catch(error){toast(t(error.key||'connectionError'));}return;}
 if(d.ttChange){state.tt.picking=true;render();return;}
 if(d.ttTo){state.tt.to=d.ttTo;render();await ttFind();return;}
