 if(d.ttJourney){const stop=state.stop;state.view='explore';state.pane='search';state.sheet=true;state.mode='destination';state.from={name:stop.name,lat:stop.lat,lng:stop.lng};state.origin=stop.name;state.query=state.tt.to||'';state.to=null;render();return;}
 if(d.ttPlan){await showTimetable(d.ttPlan,'',{toName:state.tt.trip?.to||'',target:state.tt.by||''});return;}
 if(d.rowToggle){state.openRow=state.openRow===d.rowToggle?null:d.rowToggle;const box=document.querySelector('#live-content');if(box)box.innerHTML=liveContent();loadKudos();box?.querySelector('.tado-row.open')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}if(d.timetable){await showTimetable(d.timetable,d.towards||'');return;}if(d.ttGroup!==undefined){openTimetable.group=Number(d.ttGroup);openTimetable.run=null;openTimetable.trip=null;drawTimetable();return;}if(d.ttMode){openTimetable.mode=d.ttMode;drawTimetable();return;}if(d.ttRun!==undefined){openTimetable.run=Number(d.ttRun);drawTimetable();return;}if(d.ttStop!==undefined){openTimetable.groups[openTimetable.group].stop=Number(d.ttStop);openTimetable.run=null;drawTimetable();return;}if(d.ttDay){const now=openTimetable.groups[openTimetable.group],list=openTimetable.groups.filter(x=>x.day===d.ttDay),same=list.find(x=>x.end===now.end)||list[0];openTimetable.group=openTimetable.groups.indexOf(same);openTimetable.run=null;openTimetable.trip=null;drawTimetable();return;}if(d.route){await selectRoute(d.route);return;}if(d.arrivalRoute){if(state.stopSheet){state.stopSheet=false;dialog.close();}if(state.view==='timetable'){state.view='explore';state.pane='search';state.sheet=true;}await selectRoute(d.arrivalRoute);return;}if(d.stop){await chooseStop(d.stop);return;}
 if(d.save){const id=d.save,r=[...state.favorites,state.route,...(state.results?.kind==='routes'?state.results.items:[])].find(r=>r?.id===id);if(!r)return;const way=state.routeGroup?.no===r.number?state.routeGroup.groups.find(g=>g.variantIds.includes(id)):null;await setRouteFav(way&&!r.start?{...r,start:way.from,end:way.to}:r);render();return;}
 if(d.deleteReview){if(!confirm(t('deleteConfirm')))return;await api(`/api/reviews/${d.deleteReview}`,{method:'DELETE'});toast(t('reviewDeleted'));await showReviews();return;}
 if(d.path){await selectPath(state.paths.find(p=>p.id===d.path));return;}if(d.pathDetail){showPathDetail(d.pathDetail);return;}
 if(d.category){state.category=d.category;render();return;}if(d.post){await openPost(d.post);return;}
